'use strict';
const paths={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',checksquare:'m9 11 3 3L22 4M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',folder:'M20 20H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5l2 2h9a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12a2 2 0 0 0 4 0',arrow:'M4 12h15m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',megaphone:'m3 11 18-6v14L3 13v-2m4 4 1 6h3l-1-5M21 9h2m-2 6h2',book:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2M8 6h8m-8 4h6',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4',check:'m5 12 4 4L19 6',x:'m6 6 12 12M6 18 18 6',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bookmark:'M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2Z',download:'M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4m4-3 5 5 5-5M12 17V3',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',mail:'m22 6-10 7L2 6M4 4h16a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',refresh:'M20 7v5h-5M4 17v-5h5M6 5a8 8 0 0 1 13 3M5 16a8 8 0 0 0 13 3',coffee:'M18 8h1a3 3 0 1 1 0 6h-1M3 8h15v9a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3ZM6 2v3m4-3v3m4-3v3'};
paths.file='M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Zm0 0v6h6M8 13h8m-8 4h6';
paths.edit='m16 3 5 5M4 20l4-1L21 6l-5-5L3 14Z';
paths.plus='M12 5v14M5 12h14';
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialDate=new Date(Date.now()+8*3600000);
const state={route:'home',taskFilter:'upcoming',resourceFilter:'全部',query:'',month:initialDate.getUTCMonth(),year:initialDate.getUTCFullYear(),selectedDay:null,bookmarks:new Set(),activityFilter:'upcoming',manageTab:'activities'};
const now=()=>Date.now();
const today=()=>new Date(now()+8*3600000).toISOString().slice(0,10);
const monthCourses=()=>courses.filter(c=>c.date.startsWith(today().slice(0,7))).length;
const weekdays=['日','一','二','三','四','五','六'];
const weekday=d=>weekdays[new Date(d.slice(0,10)+'T12:00:00+08:00').getUTCDay()];
const prettyDate=d=>d.slice(0,10).replaceAll('-','/');
const dateTime=d=>`${prettyDate(d)} ${d.slice(11,16)}`;
const monthDay=d=>`${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`;
const publishedTasks=()=>tasks.slice().sort((a,b)=>Date.parse(a.due)-Date.parse(b.due));
const upcomingTasks=()=>publishedTasks().filter(t=>Date.parse(t.due)>now());
const sortedActivities=()=>activities.slice().sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));
const upcomingActivities=()=>sortedActivities().filter(a=>Date.parse(a.end)>now());
const dayDiff=d=>Math.ceil((Date.parse(d)-now())/86400000);
function remaining(due){const ms=Date.parse(due)-now();if(ms<=0)return {ms:0,full:'已截止',value:'',unit:'已截止'};const total=Math.max(1,Math.floor(ms/1000)),d=Math.floor(total/86400),h=Math.floor(total%86400/3600),m=Math.floor(total%3600/60),s=total%60;return {ms,full:`${d}天 ${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`,value:d||h||Math.max(1,Math.ceil(ms/60000)),unit:d?'天':h?'小时':'分钟'};}
const navItems=[['home','home','首页'],['schedule','calendar','课表'],['todos','file','待办'],['resources','folder','资料'],['classroom','users','班级']];
const validRoutes=[...navItems.map(n=>n[0]),'activities','manage'];
const heading=(name,title,action='',label='查看全部',count='')=>`<div class="panel-heading"><div class="heading-title">${icon(name)}<h2>${esc(title)}</h2>${count!==''?`<span class="count-badge">${count}</span>`:''}</div>${action?`<button class="text-link" ${action}>${esc(label)}${icon('arrow')}</button>`:''}</div>`;
const viewTitle=(title,sub,action='',eyebrow='PHOENIX CLASS 03')=>`<div class="view-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${action}</div>`;
const empty=(title,body,action='')=>`<div class="empty-state">${icon('coffee')}<h3>${esc(title)}</h3><p>${esc(body)}</p>${action}</div>`;
const publicationNote=()=>`<p class="publication-note">${icon('info')}班级管理员统一发布 · 仅供信息查阅</p>`;
function hero(){return `<section class="hero" aria-label="班级 Banner"><div class="hero-copy"><div class="hero-eyebrow">FUDAN MBA <span>CLASS OF 2026</span></div><h2>凤凰3班</h2><p class="hero-subtitle">2026级 · 复旦大学 MBA</p><p class="hero-motto">橙启新序，<span>共赴同行</span></p></div><div class="hero-identity"><img class="hero-logo" src="./assets/phoenix-logo.svg" alt="凤凰3班班级 Logo" width="123" height="167"></div><div class="hero-bottom"><div class="hero-stat"><strong>2026</strong>级 MBA</div><div class="hero-stat"><strong>${monthCourses()}</strong>节本月课程</div><div class="hero-stat"><strong>${activities.length}</strong>场班级活动</div></div></section>`;}
function courseRow(c){const n=dayDiff(c.date+'T00:00:00+08:00');return `<button class="course-row" data-course="${esc(c.id)}" aria-label="查看${c.date} ${esc(c.title)}课程详情"><span class="course-date"><strong>${c.date.slice(8)}</strong><span>${Number(c.date.slice(5,7))}月 · 周${weekday(c.date)}</span></span><span class="course-info"><h3>${esc(c.title)}</h3><span class="course-meta">${icon('clock')}${c.start}–${c.end}<span>·</span>${esc(c.teacher)}</span><span class="course-meta course-place">${icon('pin')}${esc(c.room)}</span></span><span class="course-right"><span class="badge ${n<=3?'badge-orange':'badge-gray'}">${n>0?`${n}天后`:n===0?'今天':'已结束'}</span>${icon('chevron','course-arrow')}</span></button>`;}
function dueMarkup(t){const r=remaining(t.due);return r.ms?`<small>距截止</small><strong>${r.value}</strong>${r.unit}`:'已截止';}
function assignmentRow(t,index=0,full=false){return `<button class="assignment-row" data-task="${esc(t.id)}" aria-label="查看作业：${esc(t.title)}"><span class="assignment-index">${String(index+1).padStart(2,'0')}</span><span class="assignment-info"><strong>${esc(t.title)}</strong><p>${esc(full?t.course:t.short)} · ${esc(t.publisher)}</p><p class="assignment-date">${prettyDate(t.due)} ${t.due.slice(11,16)} 截止</p></span><span class="assignment-due" data-due="${esc(t.id)}">${dueMarkup(t)}</span></button>`;}
function deadlineStrip(){const t=upcomingTasks()[0];return t?`<div class="deadline-strip">${icon('clock')}最近截止 <span data-countdown="${esc(t.id)}">${remaining(t.due).full}</span></div>`:`<div class="deadline-strip">近期暂无未截止作业</div>`;}
function noticeRow(n){return `<button class="notice-row" data-notice="${esc(n.id)}"><span class="badge ${n.tag==='重要'?'badge-orange':'badge-gray'}">${esc(n.tag)}</span><strong>${esc(n.title)}</strong><time datetime="${n.date}">${n.date.replaceAll('-','.')}</time>${icon('chevron')}</button>`;}
function activityStatus(a){return Date.parse(a.end)<=now()?'已结束':Date.parse(a.start)<=now()?'进行中':'即将开始';}
function activityCard(a){const image=visuals[a.imageKey];return `<article class="event-card">${image?`<div class="event-cover"><img src="${image.src}" alt="${esc(image.alt)}" loading="lazy"><span class="badge">${activityStatus(a)}</span><span class="event-image-label">${a.imageKey==='campus'?'校园实景 · 活动为模拟':'氛围示意'}</span></div>`:''}<div class="event-body"><div class="event-category">${esc(a.category)} · CLASS GATHERING</div><h3>${esc(a.title)}</h3><p class="event-description">${esc(a.description)}</p><div class="event-meta"><span>${icon('calendar')}${monthDay(a.start)} 周${weekday(a.start)} · ${a.start.slice(11,16)}–${a.end.slice(0,10)===a.start.slice(0,10)?'':monthDay(a.end)+' '}${a.end.slice(11,16)}</span><span>${icon('pin')}${esc(a.location)}</span></div><div class="event-bottom"><div class="event-count"><strong>${a.participants}</strong>人参加<small>管理员统一登记</small></div><button class="text-link" data-activity="${esc(a.id)}">活动详情${icon('arrow')}</button></div><p class="event-contact">对接人：${esc(a.contactName)} · ${esc(a.contactRole)}</p></div></article>`;}
function activitiesSection(){const list=upcomingActivities().slice(0,2);return `<section class="events-section"><div class="section-heading"><div><h2>相聚，课堂之外</h2><p>班级活动 · 管理员统一更新</p></div><button class="text-link" data-route="activities">全部活动${icon('arrow')}</button></div><div class="event-grid">${list.map(activityCard).join('')}</div>${list.length?'':empty('近期暂无班级活动','新的相聚，敬请期待。')}</section>`;}
function homeView(){const next=courses.filter(c=>Date.parse(c.date+'T'+c.end+':00+08:00')>now()).slice(0,2);return `<div class="page-greeting"><h1>班级近况</h1><span class="date-label">${monthDay(today())} · 星期${weekday(today())}</span></div>${hero()}<div class="home-grid"><section class="panel courses-panel">${heading('calendar','接下来的课程','data-route="schedule"','查看课表')}<div class="course-list">${next.length?next.map(courseRow).join(''):empty('暂无近期课程','新的课程安排将在这里展示。')}</div></section><section class="panel todo-panel">${heading('file','作业通知','data-route="todos"','全部作业',upcomingTasks().length)}${upcomingTasks().length?upcomingTasks().slice(0,3).map((t,i)=>assignmentRow(t,i)).join(''):empty('暂无未截止作业','已截止的作业可以在全部作业中查看。')}${deadlineStrip()}</section><section class="quick-panel">${heading('sparkles','快速入口')}<div class="quick-grid">${[['calendar','课表','data-route="schedule"'],['file','作业','data-route="todos"'],['coffee','活动','data-route="activities"'],['book','课件','data-quick-resource="课件"'],['megaphone','公告','data-action="announcements"'],['users','同学','data-action="members"']].map(([i,t,a])=>`<button class="quick-button" ${a}><span class="quick-icon">${icon(i)}</span><strong>${t}</strong></button>`).join('')}</div></section>${activitiesSection()}<section class="panel notice-panel">${heading('megaphone','班级公告','data-action="announcements"')}${notices.length?notices.map(noticeRow).join(''):empty('暂无公告','班级公告将在这里发布。')}</section></div>`;}
function renderNav(){const active=['activities','manage'].includes(state.route)?'classroom':state.route;document.querySelector('.bottom-nav').innerHTML=navItems.map(([route,i,label])=>`<a href="#${route}" class="nav-item ${active===route?'active':''}" ${active===route?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');}
function render(){const views={home:homeView,schedule:scheduleView,todos:todosView,resources:resourcesView,classroom:classroomView,activities:activitiesView,manage:manageView};document.querySelector('main').innerHTML=sourceBanner()+views[state.route]();document.querySelector('.site-footer span').textContent=connection.mode==='live'?'内容由班级维护同学在飞书统一更新 · 北京时间':dataMessage();renderNav();updateCountdowns();}
function navigate(route){if(!validRoutes.includes(route))route='home';if(location.hash!==`#${route}`){location.hash=route;return;}state.route=route;render();window.scrollTo({top:0,behavior:'instant'});}
function calendarDays(){const first=(new Date(Date.UTC(state.year,state.month,1)).getUTCDay()+6)%7;const total=new Date(Date.UTC(state.year,state.month+1,0)).getUTCDate();let html='<span aria-hidden="true"></span>'.repeat(first);for(let d=1;d<=total;d++){const date=`${state.year}-${String(state.month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,has=courses.some(c=>c.date===date);html+=`<button class="day-button ${has?'has-course':''} ${date===today()?'today':''} ${date===state.selectedDay?'selected':''}" data-day="${date}" aria-label="${state.year}年${state.month+1}月${d}日${has?'，有课程':''}" aria-pressed="${date===state.selectedDay}">${d}</button>`;}return html;}
function scheduleView(){const date=state.selectedDay;const filtered=courses.filter(c=>date?c.date===date:c.date.startsWith(`${state.year}-${String(state.month+1).padStart(2,'0')}`));return `${viewTitle('班级课表','2026级 · 班级统一课程安排',`<button class="secondary-button" data-action="month-today">返回本月</button>`,'THE CLASS SCHEDULE')}<div class="two-columns"><section class="panel"><div class="calendar-toolbar"><h2>${state.year}年 ${state.month+1}月</h2><div class="calendar-controls"><button class="icon-button" data-month-change="-1" aria-label="上个月">${icon('left')}</button><button class="icon-button" data-month-change="1" aria-label="下个月">${icon('chevron')}</button></div></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(d=>`<span class="weekday">${d}</span>`).join('')}${calendarDays()}</div><div class="calendar-key"><i></i>有课程安排</div><p class="subtle-note">点击日期查看当天课程 · 北京时间</p></section><section class="panel">${heading('calendar',date?monthDay(date):'本月课程',date?'data-action="clear-day"':'',date?'全部课程':'')}<p class="schedule-meta-heading">${date?'星期'+weekday(date):'班级统一课程安排'} · ${filtered.length} 节课</p>${filtered.length?filtered.map(c=>`<div class="schedule-course">${courseRow(c)}</div>`).join(''):empty('暂无课程安排',date?'这一天没有课程。':'当前月份暂无已发布课程。',`<button class="secondary-button" data-action="month-today">返回本月课表</button>`)}</section></div>`;}
function todosView(){const list=publishedTasks().filter(t=>state.taskFilter==='all'||(state.taskFilter==='expired'?Date.parse(t.due)<=now():state.taskFilter==='week'?Date.parse(t.due)>now()&&Date.parse(t.due)-now()<=7*86400000:Date.parse(t.due)>now()));return `${viewTitle('作业通知','课程要求与截止时间，由班级管理员统一发布','','COURSE ASSIGNMENTS')}<div class="summary-strip"><div class="summary-item"><strong>${tasks.length}</strong><span>已发布作业</span></div><div class="summary-item"><strong>${tasks.filter(t=>Date.parse(t.due)>now()&&Date.parse(t.due)-now()<=7*86400000).length}</strong><span>7天内截止</span></div><div class="summary-item"><strong>${tasks.filter(t=>Date.parse(t.due)<=now()).length}</strong><span>已截止</span></div></div><div class="filters" role="group" aria-label="作业期限筛选">${[['upcoming','未截止'],['week','7天内'],['expired','已截止'],['all','全部']].map(([id,label])=>`<button class="filter-button ${state.taskFilter===id?'active':''}" data-task-filter="${id}" aria-pressed="${state.taskFilter===id}">${label}</button>`).join('')}</div><section class="panel list-panel">${heading('file','课程作业',null,'',list.length)}${list.length?list.map((t,i)=>assignmentRow(t,i,true)).join(''):empty('暂无相关作业通知','可切换其他期限查看作业安排。')}${publicationNote()}</section><div class="prototype-note">${icon('clock')}<p>截止时间均为北京时间，按当前时间计算。作业页仅发布信息，不记录个人完成状态。</p></div>`;}
function resourceMatches(r){const q=state.query.trim().toLowerCase();return (state.resourceFilter==='全部'||state.resourceFilter==='我的收藏'&&state.bookmarks.has(r.id)||state.resourceFilter===r.category)&&(!q||[r.title,r.course,r.code,r.category].some(t=>t.toLowerCase().includes(q)));}
function resourceRows(){const list=resources.filter(resourceMatches);return list.length?list.map(r=>`<div class="resource-row"><span class="file-icon">${esc(r.type)}</span><div class="resource-info"><button class="resource-title" data-resource="${r.id}">${esc(r.title)}</button><p>${esc(r.category)} · ${esc(r.date)} 更新 ${isDemo()?' · 示例文档':''}</p></div><button class="icon-button ${state.bookmarks.has(r.id)?'saved':''}" data-bookmark="${r.id}" aria-label="${state.bookmarks.has(r.id)?'取消收藏':'收藏'}${esc(r.title)}" aria-pressed="${state.bookmarks.has(r.id)}">${icon('bookmark')}</button></div>`).join(''):empty(state.resourceFilter==='我的收藏'?'收藏常用的学习资料':'没有找到相关资料',state.resourceFilter==='我的收藏'?'资料收藏仅保留在本次体验中。':'试试其他关键词，或切换分类。',`<button class="secondary-button" data-action="reset-search">查看全部资料</button>`);}
function resourcesView(){return `${viewTitle('学习资料','课堂讲义、案例与班级公共资料','','THE CLASS LIBRARY')}<div class="search-box">${icon('search')}<input id="resource-search" aria-label="搜索资料" type="search" placeholder="搜索课程、课件或关键词" value="${esc(state.query)}" autocomplete="off"></div><div class="filters" role="group" aria-label="资料分类">${['全部','课件','案例','班级资料','我的收藏'].map(c=>`<button class="filter-button ${state.resourceFilter===c?'active':''}" data-resource-filter="${c}" aria-pressed="${state.resourceFilter===c}">${c}</button>`).join('')}</div><section class="panel"><div class="filter-note" id="resource-result-count" role="status">共 ${resources.filter(resourceMatches).length} 份资料</div><div id="resource-results">${resourceRows()}</div></section><p class="subtle-note">${isDemo()?'当前资料为示例文本。':'资料链接由维护同学在飞书更新，访问权限以资料设置为准。'} 收藏仅在本次页面中保留，刷新后重置。</p>`;}
function activitiesView(){const list=sortedActivities().filter(a=>state.activityFilter==='all'||(state.activityFilter==='past'?Date.parse(a.end)<=now():Date.parse(a.end)>now()));return `<button class="back-link" data-route="classroom">${icon('left')}返回班级</button>${viewTitle('班级活动','时间、地点与对接信息，一目了然','','BEYOND THE CLASSROOM')}<div class="filters" role="group" aria-label="活动时间筛选">${[['upcoming','即将相聚'],['past','往期活动'],['all','全部活动']].map(([id,title])=>`<button class="filter-button ${state.activityFilter===id?'active':''}" data-activity-filter="${id}" aria-pressed="${state.activityFilter===id}">${title}</button>`).join('')}</div><div class="event-grid">${list.map(activityCard).join('')}</div>${list.length?'':empty('暂无活动信息','班级活动将由管理员统一更新。')}<div class="prototype-note">${icon('users')}<p>参加人数由管理员登记。参加意向、变更或咨询，请联系活动对接人；页面不提供个人报名和勾选。</p></div>`;}
function classroomView(){return `${viewTitle('我们的班级','复旦MBA 凤凰3班 · 2026级','','OUR CLASS COMMUNITY')}<div class="class-overview"><section class="class-welcome"><img class="class-logo" src="./assets/phoenix-logo.svg" alt="凤凰3班班级 Logo" width="123" height="167"><div><div class="eyebrow">FUDAN MBA · CLASS OF 2026</div><h2>凤凰3班</h2><p>课程、活动与每一次同窗相聚。</p></div><div class="class-stats"><div><strong>2026</strong><span>级 MBA</span></div><div><strong>${activities.length}</strong><span>场班级活动</span></div></div></section><section class="panel">${heading('megaphone','班级事务')}<button class="class-link" data-route="activities">${icon('coffee')}<span>班级活动</span><span class="badge badge-orange">${activities.length} 场</span>${icon('chevron')}</button><button class="class-link" data-action="announcements">${icon('megaphone')}<span>班级公告</span>${icon('chevron')}</button><button class="class-link" data-action="study-groups">${icon('users')}<span>学习小组</span>${icon('chevron')}</button></section></div><div class="all-events">${activitiesSection()}</div><section class="panel" id="members" style="margin-top:26px">${heading('users','班级同学')}<p class="subtle-note">${isDemo()?'展示6位示例同学，姓名和职务均为模拟信息。':'通讯录与学习小组信息，请联系班委获取。'}</p><div class="member-grid">${(isDemo()?members:[]).map(([n,role])=>`<div class="member-card"><span class="member-avatar">${n.slice(0,1)}</span><div><h3>${n}</h3><p>${role}</p></div></div>`).join('')}</div></section><section class="panel" style="margin-top:26px"><button class="class-link" data-quick-resource="班级资料">${icon('book')}<span>班级学习指南</span>${icon('chevron')}</button><button class="class-link" data-route="manage">${icon('edit')}<span>飞书内容维护</span>${icon('chevron')}</button><button class="class-link" data-action="about">${icon('info')}<span>关于班级空间</span>${icon('chevron')}</button></section><p class="subtle-note">${isDemo()?'尚未连接飞书，当前显示示例内容。':'内容由班级维护同学统一发布，网站不记录个人完成状态。'}</p>`;}
function manageView(){return `<button class="back-link" data-route="classroom">${icon('left')}返回班级</button>${viewTitle('飞书内容维护','课程、作业、活动、公告与资料，在飞书共同更新','','CONTENT MANAGEMENT')}<section class="panel maintenance-panel"><div class="maintenance-mark">${icon('edit')}</div><h2>${connection.maintenanceUrl?'前往班级多维表格':'等待连接班级多维表格'}</h2><p>维护同学在飞书中编辑内容，并将「发布状态」设为「已发布」。网站约每5分钟检查一次更新。</p>${connection.maintenanceUrl?`<a class="primary-button" href="${esc(connection.maintenanceUrl)}" target="_blank" rel="noopener noreferrer">前往飞书维护${icon('arrow')}</a>`:`<button class="primary-button" disabled>前往飞书维护</button><p class="subtle-note">班级表格尚未配置，连接完成后即可使用。</p>`}<p class="subtle-note">编辑需要飞书账号和表格编辑权限。浏览网站不需要登录。</p></section><section class="panel" style="margin-top:24px">${heading('refresh','同步情况')}<p>${esc(dataMessage())}</p>${connection.message?`<p class="subtle-note">${esc(connection.message)}</p>`:''}${connection.invalidRecords?`<p class="subtle-note">有 ${connection.invalidRecords} 条已发布记录因必填项、时间或链接格式问题未显示，请在飞书中检查。</p>`:''}<div class="maintenance-counts">${[['课程',courses.length],['作业',tasks.length],['活动',activities.length],['公告',notices.length],['资料',resources.length]].map(([name,count])=>`<span>${name}<strong>${count}</strong></span>`).join('')}</div><button class="secondary-button" data-action="sync-content">${icon('refresh')}检查更新</button><p class="subtle-note">草稿不会出现在网站上。刚发布的内容最长可能需要约10分钟显示；撤回内容也需要等待缓存更新。</p></section>`;}

let lastFocus=null,toastTimer;
function openDialog(content){const d=document.querySelector('dialog');if(!d.open)lastFocus=document.activeElement;document.querySelector('#dialog-body').innerHTML=content;if(!d.open)d.showModal();document.body.style.overflow='hidden';}
function closeDialog(){document.querySelector('dialog').close();}
function toast(message){const el=document.querySelector('.toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function courseDetail(id){const c=courses.find(c=>c.id===id);if(!c)return;openDialog(`<span class="badge badge-orange">${esc(c.type)}</span><h2 id="dialog-title">${esc(c.title)}</h2><dl class="detail-grid"><dt>课程时间</dt><dd>${prettyDate(c.date)} 周${weekday(c.date)}<br>${c.start}–${c.end}</dd><dt>授课教师</dt><dd>${esc(c.teacher)}</dd><dt>上课地点</dt><dd>${esc(c.room)}</dd><dt>本节主题</dt><dd>${esc(c.topic)}</dd></dl><p class="detail-copy">${esc(c.description)}</p><div class="dialog-actions"><button class="secondary-button" data-course-material="${esc(c.short)}">查看课程资料</button><button class="primary-button" data-action="close-dialog">知道了</button></div>${isDemo()?'<p class="subtle-note">模拟课程信息，仅供原型体验。</p>':''}`);}
function taskDetail(id){const t=tasks.find(t=>t.id===id);if(!t)return;openDialog(`<span class="badge badge-orange">${esc(t.course)}</span><h2 id="dialog-title">${esc(t.title)}</h2><dl class="detail-grid"><dt>截止时间</dt><dd>${dateTime(t.due)}（北京时间）</dd><dt>距离截止</dt><dd data-countdown="${esc(t.id)}">${remaining(t.due).full}</dd><dt>发布人</dt><dd>${esc(t.publisher)}</dd><dt>发布时间</dt><dd>${dateTime(t.publishedAt)}</dd><dt>提交说明</dt><dd>${esc(t.submission)}</dd></dl><p class="detail-copy">${esc(t.description)}</p>${publicationNote()}<div class="dialog-actions"><button class="secondary-button" data-course-material="${esc(t.short)}">查看课程资料</button><button class="primary-button" data-action="close-dialog">关闭详情</button></div><p class="subtle-note">此页面不记录个人完成或提交状态。倒计时按当前时间计算。</p>`);}
function activityDetail(id){const a=activities.find(a=>a.id===id);if(!a)return;openDialog(`<span class="badge badge-orange">${esc(a.category)} · ${activityStatus(a)}</span><h2 id="dialog-title">${esc(a.title)}</h2><p class="detail-copy">${esc(a.description)}</p><dl class="detail-grid"><dt>活动时间</dt><dd>${dateTime(a.start)}<br>至 ${dateTime(a.end)}（北京时间）</dd><dt>活动地点</dt><dd>${esc(a.location)}</dd><dt>参加人数</dt><dd>${a.participants} 人 · 管理员登记</dd><dt>更新时间</dt><dd>${dateTime(a.updatedAt)}</dd></dl><h3>活动内容</h3><p class="detail-copy">${esc(a.content)}</p><section class="contact-box"><h3>活动对接人</h3><p>${esc(a.contactName)} · ${esc(a.contactRole)}</p><p>${esc(a.contactInfo)}</p></section>${publicationNote()}<div class="dialog-actions"><button class="primary-button" data-action="close-dialog">知道了</button></div>${isDemo()?'<p class="subtle-note">活动、人数与联系人均为模拟信息。</p>':''}`);}
function noticeDetail(id){const n=notices.find(n=>n.id===id);if(!n)return;openDialog(`<span class="badge badge-orange">${esc(n.tag)}</span><h2 id="dialog-title">${esc(n.title)}</h2><div class="notice-detail-meta">${esc(n.author)} · ${n.date.replaceAll('-','.')}</div><p class="detail-copy">${esc(n.body)}</p>${isDemo()?'<p class="subtle-note">模拟公告，不是学校正式通知。</p>':''}<div class="dialog-actions"><button class="primary-button" data-action="close-dialog">知道了</button></div>`);}
function announcements(){openDialog(`<h2 id="dialog-title">班级公告</h2><p class="subtle-note">共 ${notices.length} 条${isDemo()?' · 模拟内容':''}</p>${notices.map(noticeRow).join('')}`);}
function resourceDetail(id){const r=resources.find(r=>r.id===id);if(!r)return;const url=safeLink(r.url);openDialog(`<span class="badge badge-orange">${esc(r.category)}${isDemo()?' · 示例文档':''}</span><h2 id="dialog-title">${esc(r.title)}</h2><p class="notice-detail-meta">${esc(r.course)} · ${esc(r.date)} 更新</p><div class="text-document">${esc(r.summary||r.content)}</div>${isDemo()?`<p class="detail-copy">${esc(r.content)}</p>`:''}<div class="dialog-actions"><button class="secondary-button" data-bookmark="${r.id}" data-resource-dialog="true">${icon('bookmark')}${state.bookmarks.has(r.id)?'取消收藏':'收藏资料'}</button>${url?`<a class="primary-button" href="${esc(url)}" target="_blank" rel="noopener noreferrer">打开资料${icon('arrow')}</a>`:isDemo()?`<button class="primary-button" data-download="${r.id}">${icon('download')}下载示例文本</button>`:''}</div>${url?'<p class="subtle-note">将在新页面打开资料，访问权限以资料提供方设置为准。</p>':''}`);}

function updateCountdowns(){document.querySelectorAll('[data-due]').forEach(el=>{const t=tasks.find(t=>t.id===el.dataset.due);if(t)el.innerHTML=dueMarkup(t);});document.querySelectorAll('[data-countdown]').forEach(el=>{const t=tasks.find(t=>t.id===el.dataset.countdown);if(t)el.textContent=remaining(t.due).full;});}
function restoreFocus(selector){document.querySelector(selector)?.focus({preventScroll:true});}
function about(){openDialog(`<h2 id="dialog-title">关于班级空间</h2><p class="detail-copy">复旦MBA 凤凰3班 · 2026级\n\n课程、作业、活动、公告与资料由维护同学在飞书统一更新。网站只展示已发布内容，不记录个人作业完成或提交状态。\n\n${isDemo()?'当前尚未连接飞书，展示内容均为示例。':'当前状态：'+dataMessage()}</p><div class="text-document"><strong>班级标识</strong><p>Logo 由班级提供，保留原始凤凰图形与配色。</p></div>`);}

document.addEventListener('input',e=>{if(e.target.id==='resource-search'){state.query=e.target.value;document.querySelector('#resource-results').innerHTML=resourceRows();document.querySelector('#resource-result-count').textContent=`共 ${resources.filter(resourceMatches).length} 份资料`;}});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-route]');if(!b)return;
if(b.dataset.route){navigate(b.dataset.route);return;}
if(b.dataset.course){courseDetail(b.dataset.course);return;}
if(b.dataset.task){taskDetail(b.dataset.task);return;}
if(b.dataset.notice){noticeDetail(b.dataset.notice);return;}
if(b.dataset.activity){activityDetail(b.dataset.activity);return;}
if(b.dataset.resource){resourceDetail(b.dataset.resource);return;}
if(b.dataset.courseMaterial){closeDialog();state.resourceFilter='全部';state.query=b.dataset.courseMaterial;navigate('resources');return;}
if(b.dataset.quickResource){state.resourceFilter=b.dataset.quickResource;state.query='';navigate('resources');return;}
if(b.dataset.taskFilter){state.taskFilter=b.dataset.taskFilter;render();restoreFocus(`[data-task-filter="${b.dataset.taskFilter}"]`);return;}
if(b.dataset.resourceFilter){state.resourceFilter=b.dataset.resourceFilter;render();restoreFocus(`[data-resource-filter="${b.dataset.resourceFilter}"]`);return;}
if(b.dataset.activityFilter){state.activityFilter=b.dataset.activityFilter;render();restoreFocus(`[data-activity-filter="${b.dataset.activityFilter}"]`);return;}
if(b.dataset.monthChange){const d=new Date(Date.UTC(state.year,state.month+Number(b.dataset.monthChange),1));state.year=d.getUTCFullYear();state.month=d.getUTCMonth();state.selectedDay=null;render();restoreFocus(`[data-month-change="${b.dataset.monthChange}"]`);return;}
if(b.dataset.day){state.selectedDay=state.selectedDay===b.dataset.day?null:b.dataset.day;render();restoreFocus(`[data-day="${b.dataset.day}"]`);return;}
if(b.dataset.bookmark){const id=b.dataset.bookmark;if(state.bookmarks.has(id))state.bookmarks.delete(id);else state.bookmarks.add(id);render();if(b.dataset.resourceDialog)resourceDetail(id);else restoreFocus(`[data-bookmark="${id}"]`);toast(state.bookmarks.has(id)?'已收藏，限本次体验':'已取消收藏');return;}
if(b.dataset.download){const r=resources.find(r=>r.id===b.dataset.download);if(!r)return;const url=URL.createObjectURL(new Blob([r.title+'\n\n'+r.content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=r.title+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('示例文本已准备下载');return;}
switch(b.dataset.action){case 'sync-content':loadClassContent();break;case 'close-dialog':closeDialog();break;case 'announcements':announcements();break;case 'members':navigate('classroom');setTimeout(()=>document.querySelector('#members')?.scrollIntoView({block:'start'}),0);break;case 'month-today':state.month=Number(today().slice(5,7))-1;state.year=Number(today().slice(0,4));state.selectedDay=null;render();break;case 'clear-day':state.selectedDay=null;render();break;case 'reset-search':state.resourceFilter='全部';state.query='';render();break;case 'about':about();break;case 'study-groups':if(!isDemo()){openDialog('<h2 id="dialog-title">学习小组</h2><p class="detail-copy">学习小组信息请向班委获取，或查看班级资料中的相关文档。</p>');break;}openDialog(`<h2 id="dialog-title">学习小组</h2><p class="subtle-note">48位同学 · 8个学习小组（模拟）</p><div class="text-document"><h3>第1组 · 周明</h3><p>本周主题：线性规划模型的构建</p><h3>第2组 · 许安然</h3><p>本周主题：团队沟通与案例阅读</p><h3>第3组 · 陆川</h3><p>本周主题：三张财务报表的关联</p></div><p class="subtle-note">展示3个示例小组，尚未接入真实分组名单。</p>`);break;}
});
document.querySelector('dialog').addEventListener('close',()=>{document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else document.querySelector('main').focus({preventScroll:true});});
document.querySelector('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();document.querySelector('main').focus();});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
navigate(location.hash.slice(1)||'home');loadClassContent();setInterval(updateCountdowns,1000);setInterval(()=>{if(!document.hidden)loadClassContent();},300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadClassContent();});
// Read-only tools expose published class information; there is no completion mutation.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const validate=input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('参数必须为空对象');};const defs=[{name:'list_class_assignments',title:'查看班级作业通知',description:'读取当前页面的作业通知及数据来源，不包含个人完成状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){validate(input);return {source:connection.mode,syncedAt:connection.syncedAt,items:publishedTasks().map(t=>({id:t.id,title:t.title,course:t.course,due:t.due,publisher:t.publisher}))};}},{name:'list_class_activities',title:'查看班级活动信息',description:'读取当前页面的活动内容、时间地点、参加人数与对接人信息及数据来源。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){validate(input);return {source:connection.mode,syncedAt:connection.syncedAt,items:sortedActivities().map(a=>({id:a.id,title:a.title,content:a.content,start:a.start,end:a.end,location:a.location,participants:a.participants,contactName:a.contactName,contactRole:a.contactRole,contactInfo:a.contactInfo}))};}}];for(const tool of defs){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
